from pathlib import Path
from html import escape as h
import json,base64
Q=Path('qa21');R=Path('work/Chocobo_QA20_V2');v=json.loads((Q/'verification.json').read_text());s=json.loads((Q/'supplemental_verification.json').read_text());m=json.loads((R/'manifest.json').read_text());tr=json.loads((Q/'translations.json').read_text());reviews=json.loads((Q/'linguistic_review.json').read_text())
def img(p,caption):return '<figure><img width="224" height="157" src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'" alt="'+h(caption)+'"><figcaption>'+h(caption)+'</figcaption></figure>'
def pages(id,prefix):
 d=Q/'runs'/(prefix+id.replace(':','_'));seen=set();out=[]
 for p in sorted(d.glob('page_*.png'))+list(d.glob('end_text.png')):
  if p.read_bytes()in seen:continue
  seen.add(p.read_bytes());out.append(img(p,id+' · '+p.stem))
 return ''.join(out)
examples=[]
for id in ['G06:M019','G06:M066','G06:M081','G07:M000','G08:M028']:
 examples.append('<article><h3>'+id+'</h3><p>'+h(tr[id]['reason'])+'</p><div class="comparison"><div><h4>Antes · HF15</h4><div class="screens">'+pages(id,'baseline_')+'</div></div><div><h4>Después · HF16</h4><div class="screens">'+pages(id,'verified_')+'</div></div></div></article>')
rows=''.join('<tr><td>'+id+'</td><td>'+h(x['text'])+'</td><td>'+h(x['reason'])+'</td></tr>'for id,x in sorted(tr.items()))
details=[]
for x in reviews:
 details.append('<details><summary>'+x['id']+' · '+('Reserva'if x['status']=='NEEDS_CONTEXT'else'PASS sintético acotado')+(' · corregida'if x['changed']else'')+'</summary><p>'+h(x['reason'])+'</p><p class="muted">'+h(x['context_limit'])+'</p><div class="screens">'+''.join(img(R/p,Path(p).name)for p in x['final_images'])+'</div></details>')
style=Path('delivery/Chocobo_EN_HF15_QA20_V2_Informe.html').read_text().split('<style>')[1].split('</style>')[0]
html='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chocobo · QA21 V3 · HF16 TEST</title><style>'+style+'</style><main>'
html+='''<header><div class="eyebrow">CHOCOBO WONDER SWAN · INGLÉS · QA21</div><h1>Validación visual y lingüística<br>3 de 5 · HF16 TEST</h1><p>Revisión de las 207 referencias previstas de G06, G07, G08, G10 y G11. La aprobación global sigue abierta.</p></header><div class="badges"><div class="badge"><b>207</b>referencias revisadas</div><div class="badge"><b>64</b>diálogos corregidos</div><div class="badge"><b>205</b>PASS sintéticos acotados</div><div class="badge"><b>2</b>reservas del lote</div></div><div class="callout"><strong>V3 ejecutada con reservas.</strong> G06:M100 necesita su consumidor de depuración; G11:M011 necesita el número de plantas y su ventana compuesta. Quedan V4, V5 y las reservas heredadas.</div>
<h2>Qué cambió</h2><p>Se reparó una frase ilegible sobre el crecimiento del pueblo, una repetición de Item File y errores de sujeto, cantidad y sentido en los libros, el cristal y los diálogos de los personajes. Se recuperaron frases omitidas y se corrigió la gramática. Se conserva la fuente nativa y su cuadrícula.</p><p>Los 64 textos usan 4480 bytes de espacio verificado del banco 06, con 64 punteros del mismo banco. Hay 4258 bytes distintos frente a HF15. El motor, el título y el guardado permanecen iguales. Dos getters de propiedades cambian en su espacio original.</p>
<h2>Antes y después</h2><p class="muted">Capturas nativas de 224 × 157, con un área de juego de 224 × 144. La selección de diálogo es sintética; el personaje y el fondo no identifican al hablante. Las láminas japonesas del corpus completo se conservan en las fuentes.</p>'''+''.join(examples)
html+='<h2>Objetos, cantidades y nombres compuestos</h2><p>'+h(s['user_summary'])+'</p><p class="muted">Comparación con la ROM japonesa y lectura de los consumidores reales de menú después de preparar inventarios sintéticos. Esta muestra no acredita todos los objetos ni los 2333 getters.</p><div class="screens">'
for x in s['report_images']:html+=img(Q/'runs'/x['path'],x['caption'])
html+='</div><p>F06:I019: <strong>Strong vs undead</strong>. F06:I022: <strong>Strong vs poison foes</strong>. Las dos propiedades expresan eficacia contra tipos de enemigos, no resistencia al estado veneno.</p><h2>Integridad y alcance</h2><table><tr><th>Comprobación</th><th>Resultado</th></tr>'
for a,b in [('Diálogos',f"207 sesiones de HF16; {v['story_terminators_reached']} terminadores. {v['native_frames']} cuadros."),('Presentación',f"{v['visual_readings']} capturas registradas; ningún glifo no vacío descartado en las 205 referencias aprobadas."),('Integridad',f"{v['checks']} controles del lote y {s['checks']} complementarios; 11 pruebas del proyecto."),('Reconstrucción','Generador editable y builder acumulativo: ROM idéntica. BPS aplicado por una implementación independiente: igualdad exacta.'),('Límites','Sin recorrido natural completo, segundo revisor, segundo emulador ni hardware. Las reservas anteriores continúan.')]:html+='<tr><td>'+h(a)+'</td><td>'+h(b)+'</td></tr>'
html+='''</table><p>Se mantiene pendiente G16:M073, preset32/F00:I053 y los consumidores G16:M000/M003/M004, además de las seis reservas de V2. La matriz de guardado histórica se hereda por integridad de bytes; no se presenta como una prueba nueva de esta fase.</p><h2>Los 64 diálogos corregidos</h2><div class="tablewrap"><table><tr><th>Referencia</th><th>Inglés final editable</th><th>Motivo</th></tr>'''+rows+'</table></div><h2>Registro visual completo</h2>'+''.join(details)
html+='''<h2>Continuación y entrega</h2><p>V4: 194 referencias de G09. V5: 154 de G14 y revisión transversal de terminología, gráficos, créditos y reservas. No se añade otra fase automáticamente.</p><p>Aplicar el BPS acumulativo HF16 directamente a la ROM japonesa limpia, CRC32 <strong>CCAA4853</strong>. El paquete contiene fuentes editables acumulativas, pruebas, capturas y checkpoints. No incluye ROM comercial, BIOS ni emulador.</p><p class="muted">SHA-256 ROM HF16<br><code>'''+m['target']['sha256']+'</code><br>SHA-256 BPS<br><code>'+m['bps_sha256']+'</code></p><footer>QA21 · HF16 TEST · Revisión sintética acotada. Las dos reconstrucciones desde extracciones nuevas y la trazabilidad están documentadas en el paquete.</footer></main></html>'
(R/'QA21_V3_Informe.html').write_text(html);p=Path('delivery/Chocobo_EN_HF16_QA21_V3_Informe.html');p.write_text(html);print({'report':str(p),'bytes':p.stat().st_size,'references':len(details)})
